import Link from 'next/link';
import { notFound } from 'next/navigation';
import type { Metadata } from 'next';
import { SECTION_META, getTopic, getWeightage } from '@/lib/content';
import type { SectionId } from '@/lib/sections';
import { Md } from '@/components/Md';

export const dynamic = 'force-static';
// (section, topic) params are generated by the [topic] layout above this page.

export async function generateMetadata({ params }: { params: Promise<{ section: string; topic: string }> }): Promise<Metadata> {
  const { section, topic } = await params;
  const t = getTopic(section as never, topic);
  if (!t) return {};
  const nFormulas = t.subtopics.reduce((n, s) => n + (s.formulas?.length ?? 0), 0);
  const nTricks = t.subtopics.reduce((n, s) => n + (s.tricks?.length ?? 0), 0);
  return {
    title: `${t.title}: notes, formulas, shortcut tricks & practice`,
    description: `${t.title} for SSC, Railway & other govt exams: ${nFormulas}+ formulas, ${nTricks} shortcut tricks with examples, recurring PYQ patterns, solved questions and a ${t.practice?.length ?? 0}-question topic test.`,
  };
}

const FREQ_CHIP: Record<string, string> = { 'very common': 'chip-high', common: 'chip-medium', occasional: 'chip-low' };
const DIFF_COLORS: Record<string, string> = { easy: 'var(--ok)', medium: 'var(--warn)', hard: 'var(--bad)' };

export default async function TopicOverviewPage({ params }: { params: Promise<{ section: string; topic: string }> }) {
  const { section, topic } = await params;
  const t = getTopic(section as never, topic);
  if (!t) notFound();
  const meta = SECTION_META[section as SectionId];
  const weight = getWeightage();
  const wRow = (weight?.sections?.[t.sectionId as string] ?? []).find((r: any) => r.topicId === t.id);
  const diff = { easy: 0, medium: 0, hard: 0 } as Record<string, number>;
  (t.practice ?? []).forEach((q) => { if (q.difficulty && diff[q.difficulty] !== undefined) diff[q.difficulty]++; });
  const diffTotal = diff.easy + diff.medium + diff.hard;
  const base = `/${t.sectionId}/${t.id}`;
  const subTitle = Object.fromEntries(t.subtopics.map((s) => [s.id, s.title]));

  const inside = [
    { href: `${base}/learn/`, icon: '📖', title: `Learn — ${t.subtopics.length} subtopics`, body: 'One page per subtopic: detailed notes, every question type, formulas, tricks and practice sets.' },
    { href: `${base}/formulas/`, icon: '⚡', title: 'Formula sheet', body: 'Every formula on one printable page, grouped by subtopic.' },
    { href: `${base}/examples/`, icon: '✍️', title: 'Solved examples', body: `${t.solvedExamples?.length ?? 0} exam-level questions worked step by step.` },
    { href: `${base}/practice/`, icon: '🎯', title: 'Practice & test', body: `${t.practice?.length ?? 0} questions — untimed practice or a timed test with analysis.` },
  ];

  return (
    <div>
      <Md className="mt-4 text-[15px]">{t.summary}</Md>

      {t.subtopics[0] && (
        <div className="flex gap-2 mt-4 flex-wrap">
          <Link href={`${base}/learn/${t.subtopics[0].id}/`} className="btn btn-brand">Start learning →</Link>
          <Link href={`${base}/practice/`} className="btn">Take the test</Link>
        </div>
      )}

      <div className="grid sm:grid-cols-2 gap-3 mt-5">
        {inside.map((c) => (
          <Link key={c.href} href={c.href} className="card p-4 hover:-translate-y-0.5 transition-transform">
            <div className="text-xl">{c.icon}</div>
            <div className="font-bold text-sm mt-1">{c.title}</div>
            <p className="text-xs muted mt-0.5">{c.body}</p>
          </Link>
        ))}
      </div>

      {(wRow || diffTotal > 0) && (
        <section className="card p-5 mt-8">
          <h2 className="text-lg font-extrabold">Track record in the exam</h2>
          {wRow && (
            <>
              <div className="flex gap-2 mt-3 flex-wrap text-sm">
                <span className="chip chip-high">avg {wRow.avg?.toFixed?.(1) ?? wRow.avg} Q / shift</span>
                {Object.entries(wRow.counts ?? {}).map(([y, c]) => <span key={y} className="chip">{y}: {String(c)} Q</span>)}
              </div>
              <p className="text-xs faint mt-2">Questions per shift in recent SSC CGL papers.</p>
            </>
          )}
          {diffTotal > 0 && (
            <div className="mt-4">
              <h3 className="text-xs font-bold uppercase tracking-wide faint">Test difficulty mix ({diffTotal} questions)</h3>
              <div className="flex h-2.5 rounded-full overflow-hidden mt-2" style={{ background: 'var(--surface-2)' }}>
                <div style={{ width: `${(diff.easy / diffTotal) * 100}%`, background: DIFF_COLORS.easy }} />
                <div style={{ width: `${(diff.medium / diffTotal) * 100}%`, background: DIFF_COLORS.medium }} />
                <div style={{ width: `${(diff.hard / diffTotal) * 100}%`, background: DIFF_COLORS.hard }} />
              </div>
              <div className="flex gap-3 text-xs faint mt-1.5">
                <span>{diff.easy} easy</span><span>{diff.medium} medium</span><span>{diff.hard} hard</span>
              </div>
            </div>
          )}
        </section>
      )}

      {t.pyqPatterns && t.pyqPatterns.length > 0 && (
        <>
          <h2 className="text-2xl font-extrabold mt-10">Question patterns exams keep repeating</h2>
          <p className="text-sm muted mt-1">Taken from previous-year papers. If a pattern is marked "very common", expect to see it in your exam.</p>
          <div className="space-y-2.5 mt-3">
            {t.pyqPatterns.map((p, k) => (
              <div key={k} className="card p-4">
                <div className="flex items-center gap-2 flex-wrap">
                  <h3 className="font-bold text-sm">{p.pattern}</h3>
                  {p.frequency && <span className={`chip ${FREQ_CHIP[p.frequency] ?? ''}`}>{p.frequency}</span>}
                </div>
                {p.howToSpot && <div className="text-sm mt-1.5"><b>Spot it:</b> <Md inline>{p.howToSpot}</Md></div>}
                {p.approach && <Md className="text-sm mt-1">{`**How to solve:** ${p.approach}`}</Md>}
                {p.example && (
                  <div className="mt-2.5 rounded-xl p-3 text-sm" style={{ background: 'var(--surface-2)' }}>
                    <Md className="font-semibold">{`**Example:** ${p.example.q}`}</Md>
                    <Md className="mt-1">{p.example.solution}</Md>
                  </div>
                )}
                {p.subtopic && subTitle[p.subtopic] && (
                  <Link href={`${base}/learn/${p.subtopic}/`} className="text-xs underline decoration-dotted mt-2 inline-block">Learn this in “{subTitle[p.subtopic]}” →</Link>
                )}
              </div>
            ))}
          </div>
        </>
      )}

      <div className="card p-5 mt-8" style={{ borderTop: `3px solid ${meta.color}` }}>
        <h2 className="font-extrabold">Your next step</h2>
        <p className="text-sm muted mt-1">New here? Start with subtopic 1 in <Link className="underline" href={`${base}/learn/`}>Learn</Link>. Revision mode? Jump straight to the <Link className="underline" href={`${base}/practice/`}>test</Link> and let it tell you what to fix.</p>
      </div>
    </div>
  );
}
